  const autonomyFactors = [t6("Battery capacity","Capacidad de la batería","Capacità della batteria","Capacité de la batterie","Pojemność baterii","Ёмкость батареи"),t6("Available energy in kWh","Energía disponible en kWh","Energia disponibile in kWh","Énergie disponible en kWh","Dostępna energia w kWh","Доступная энергия в кВтч"),t6("Terrain","Terreno","Terreno","Terrain","Teren","Местность"),t6("Speed","Velocidad","Velocità","Vitesse","Prędkość","Скорость"),t6("Tires","Neumáticos","Pneumatici","Pneus","Opony","Шины"),t6("Motor","Motor","Motore","Moteur","Silnik","Двигатель"),t6("Controller","Controlador","Controller","Contrôleur","Kontroler","Контроллер"),t6("Efficiency","Eficiencia","Efficienza","Efficacité","Wydajność","Эффективность"),t6("Driving style","Estilo de conducción","Stile di guida","Style de conduite","Styl jazdy","Стиль вождения")];

